import { useFormStore } from "qortex-form-react/store";

const { form, isChanged, save } = useFormStore({
  key: "profile",
  store: settingsStore,
  selector: (s) => s.profile,
  validate: { fields: { name: (v) => (!v ? "Required" : null) } },
});

await save(async (draft) => {
  await api.saveProfile(draft);
  settingsStore.set({ profile: draft }); // optional write-back
});
